insert into public.product_content_sources
  (manufacturer, page_key, source, source_label, source_url, name, tagline, description, features, clinical_applications, options, billing_codes, images, sizing_rows, sizing_note, captured_at)
values
  ('ovation-medical', 'gen2-walking-boot', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Gen 2® Walking Boot', 'The World''s Most Advanced Walker', 'Ovation''s patented Gen 2® Walking Boot has been validated as the most advanced double upright walker on the market by healthcare professionals worldwide. Designed with the patient in mind, our Gen 2® eliminates all of the issues associated with old style walking boots. Lightyears ahead of its competition, the Gen 2® is the best option for your patients.', '["Incredibly light weight and low profile.", "Intuitive Sole allows patients to track naturally with their own gait pattern.", "Shock-Pod feature results in 50% less energy being transferred to the injured limb upon each heel strike.", "Sure-Grip resting surface prevents the limb from slipping when elevated on a smooth surface.", "Sculpted frame accommodates a wide variety of patient anatomies.", "Easy single push-button release system."]'::jsonb, '["Soft tissue injuries", "Grade 2 and 3 sprains / stable fractures", "Post-operative use", "Trauma and rehab"]'::jsonb, '{"Height": ["Tall", "Short"], "Inflation": ["Pneumatic", "Non-Pneumatic"], "Color": ["Blue", "Red", "Black", "Grey"]}'::jsonb, '["L4360", "L4361", "L4386", "L4387"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'nu-form-ankle-brace', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Nu-Form™ Ankle Brace', 'Exceptional Comfort, Enhanced Stability', 'Our patented Nu-Form™ Ankle Brace combines the best features of a classic lace-up figure-8 with the support of an ankle stirrup into a low-profile, lightweight, and breathable solution. Our Fusion-Form manufacturing process allows us to provide superior support, compression, and comfort that would otherwise not be possible using the conventional cut and sew method.', '["Unique design that blends the support of a stirrup with the comfort and compressive fit of a lace-up.", "Low-profile design fits easily in all shoe categories.", "Multi-layer frame provides superior rotational protection at the mid-foot and inversion/eversion control.", "Even compression manages daily swelling patterns.", "3D spacer fabric allows heat and moisture to escape."]'::jsonb, '["Acute ankle sprains", "Post-operative support", "Ankle injury rehabilitation", "Chronic ankle instability", "Prophylactic use"]'::jsonb, '{"Size": ["X-Small", "Small", "Medium", "Large", "X-Large"]}'::jsonb, '["L1902"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'lace-up-ankle', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Lace-Up Ankle Brace', '', '', '["Durable ballistic nylon construction ensures long-lasting use.", "Even compression aids in reducing swelling and promotes healing.", "Figure-8 straps offer precise inversion/eversion control.", "Tibia strap provides additional compression and support.", "Conveniently fits into a shoe for easy and convenient wear."]'::jsonb, '["Acute ankle sprains", "Post-operative support", "Ankle injury rehabilitation", "Chronic ankle instability", "Prophylactic use"]'::jsonb, '{"Size": ["XX-Small", "X-Small", "Small", "Medium", "Large", "X-Large", "XX-Large"]}'::jsonb, '["L1902"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'ankle-stirrup', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Foam Ankle Stirrups', '', '', '["Bilateral shells for rigid support, allowing controlled dorsal and plantar flexion while managing inversion/eversion.", "Breathable low-profile liners and slim design ensure a comfortable fit in shoes.", "Convenient hook and loop closures for quick and secure clinical application.", "Bilateral shells provide rigid support, allowing dorsal and plantar flexion while controlling inversion/eversion.", "Inflatable air bladders provide a comfortable fit and actively reduce edema.", "Hook and loop closures allow for quick and convenient clinical application."]'::jsonb, '["Acute ankle sprains", "Post-operative support", "Ankle injury rehabilitation", "Chronic ankle instability", "Prophylactic use"]'::jsonb, '{"Color": ["Black", "White"], "Size": ["Youth/Universal", "Standard/Universal"]}'::jsonb, '["L4350"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'nu-form-back', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Nu-Form™ Universal Back Brace', 'Unmatched Breathability, Superior Comfort', '', '["Includes a customizable/moldable anterior panel.", "Coverage from L1-L5 for the L0627 and S1-T9 vertebra for the L0631/L0637.", "Completely breathable over the spinous process.", "Pressure relief zone automatically adjusts to provide relief at surgical sites.", "Extremely thin and low-profile, fits comfortably under clothing.", "Designed for both post-op and pain relief.", "Universally sized and easily adjustable.", "Rigid posterior panel automatically adjusts to unique patient anatomy.", "Incredibly durable, backed by a 5-year warranty."]'::jsonb, '["Lumbar Spinal Post-Op Care", "Chronic Lower Back Pain", "Lumbar Sprains and Strains", "Spondylolisthesis", "Osteoporosis", "Fracture Management", "Post-Operative Support", "Non-Specific Low Back Pain"]'::jsonb, '{"Size": ["30\"-48\"", "30\"-70\" (Extension Belt)"]}'::jsonb, '["L0627", "L0642", "L0631", "L0648", "L0637", "L0650"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'ls-double-pull-back', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Universal LS Double-Pull Back Brace', '', '', '["Includes an anterior panel.", "Coverage from L1-L5 for the L0627 and S1-T9 vertebra for the L0631/L0637.", "Universally sized.", "Easily adjustable straps allow for quick clinical application.", "Double-pull pulley system provides adjustable level of compression.", "Quality materials increase breathability and enhance comfort."]'::jsonb, '["Lumbar Spinal Post-Op Care", "Chronic Lower Back Pain", "Lumbar Sprains and Strains", "Spondylolisthesis", "Osteoporosis", "Fracture Management", "Post-Operative Support", "Non-Specific Low Back Pain"]'::jsonb, '{"Size": ["25\"-50\"", "50\"-60\""]}'::jsonb, '["L0627", "L0631", "L0637"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'lumbar-support', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Elastic Lumbar Support', '', '', '["Firm compressible lumbar pad provides optimum support.", "Quality materials increase breathability and enhance comfort.", "Overlapping elastic pull strap design provides lumbar and abdominal support."]'::jsonb, '["Chronic lower back pain", "Lumbar sprains/strains", "Spondylolisthesis", "Osteoporosis"]'::jsonb, '{"Size": ["Small", "Medium", "Large", "XLarge", "XXLarge"]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'game-changer-oa', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'The Game Changer™ OA Knee Brace', '', '', '["Universal sizing (right or left).", "Single upright design.", "Effectively treats both medial and lateral knee pain.", "Easy push-button release for quick don and doffing."]'::jsonb, '["Moderate to severe compartmental knee osteoarthritis", "Degenerative meniscal tears", "Knee conditions that may benefit from compartmental unloading"]'::jsonb, '{"Side": ["Universal Left", "Universal Right"]}'::jsonb, '["L1843", "L1851"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'neoprene-knee', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Neoprene Knee Support with Stabilized Patella', '', '', '["Universal buttress provides patellar control.", "Spiral stays for medial and lateral support.", "Breathable and low-profile design.", "Hinged medial/lateral stays provide support and control range of motion.", "Front hook and loop closures for quick clinical application.", "Anterior wraparound style accommodates all leg shape variations."]'::jsonb, '["Mild or moderate ligament joint pain", "Pain and sprains in the knee", "Compression and support reduce knee instability"]'::jsonb, '{"Size": ["Small", "Medium", "Large", "X-Large", "XX-Large", "3X-Large", "4X-Large"]}'::jsonb, '["L1810", "L1812"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'compact-pro-rom', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Compact Pro ROM Post-Op Knee Brace', '', '', '["Telescoping struts for length adjustment from 17\"-29\".", "Simple rotate and release flexion/extension settings.", "Unique safety lock feature for increased patient compliance.", "100% tool-free adjustments.", "Drop lock button.", "Quickly locks at 0°, 10°, 20°, 30°, 45°, 60°, 75° & 90°."]'::jsonb, '["ACL, PCL, MCL, and LCL knee-related repairs", "Tibia fractures", "Meniscal repairs", "Patella tendon repairs", "Condylar fractures", "Severe knee pain or stiffness", "Chronic knee inflammation and swelling"]'::jsonb, '{"Size": ["Standard", "X-Large"], "Wrap": ["Standard Wrap", "Cool Wrap"]}'::jsonb, '["L1832", "L1833"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'hybrid-night-splint', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Hybrid Night Splint', 'The Best of Both Worlds', 'Traditionally, orthopedic bracing companies have provided only two night splint options for treating plantar fasciitis and heel pain. These offerings have led to frustrated doctors, non-compliant patients, and huge gaps in recovery outcomes. Ovation''s patented Hybrid Night Splint offers more comfort than a posterior splint and better functionality than a dorsal, making it the best of both worlds.', '["Allows patients with severe heel pain to start at less than 90-degrees.", "Articulating hinge lets patients adjust the level of stretch over time.", "Holds foot securely in place without giving up comfort or mobility.", "Position (stretch) indicator window lets patients participate in their own rehab process.", "Footbed is over 40% wider than a dorsal splint, preventing toe binding."]'::jsonb, '["Plantar Fasciitis", "Achilles Tendonitis", "Heel Pain", "Drop Foot", "Post-Static Pain"]'::jsonb, '{"Size": ["Small to Medium", "Large to X-Large"]}'::jsonb, '["L4397"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'night-splint', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Posterior Night Splint', '', '', '["Bilateral straps easily adjust flexion, providing a comfortable and gradual stretch of the Plantar Fascia and Achilles Tendon.", "Dorsi-flexion can be adjusted off of 90°, allowing for a customized range of motion.", "Soft lined interior is breathable, comfortable, and washable.", "Straps are padded for comfort across the dorsum of the ankle.", "Easy-release buckles are simple to use.", "Padded shell holds the foot at a 90-degree angle, providing optimal support and promoting proper healing.", "Lightweight, low-profile dorsal design allows for easy application and improved compliance."]'::jsonb, '["Plantar fasciitis", "Achilles tendonitis", "Drop foot", "Heel pain", "Post-static pain"]'::jsonb, '{"Size": ["Small", "Medium", "Large", "Small to Medium", "Large to X-Large"]}'::jsonb, '["L4397", "L4398"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'versa-fit-wrist', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Versa-Fit™ Wrist Brace', 'Biggest improvement to the wrist & thumb category in over 20 years', 'Our patented Versa-Fit™ Wrist Brace and Versa-Fit™ Thumb Spica are the first off-the-shelf, custom fitting wrist & thumb supports. Powered by our patented Versa-Fit™ technology, the standard size fits over 90% of people, allowing you to free up shelf space and carry less product.', '["Standard size fits virtually all patients, reducing need to carry excess inventory.", "Versa-Fit™ Flex Panel automatically expands, providing a custom off-the-shelf fit.", "Auto-lock strap secures custom sizing.", "Cut low at the palmar crease to allow for 90-degree MP flexion.", "Standard size fits virtually all patients.", "Custom off-the-shelf fit.", "Neutral thumb position allows opposition.", "Auto-lock strap secures sizing."]'::jsonb, '["Carpal tunnel", "Incomplete fractures", "Tendonitis", "Soft tissue injuries", "Post-cast support for healing", "Gamekeeper''s thumb", "Dequervain''s tendonitis", "Scaphoid injuries"]'::jsonb, '{"Size": ["X-Small", "Standard", "X-Large"], "Side": ["Right", "Left"]}'::jsonb, '["L3908", "L3809"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'thumb-spica', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Nu-Form™ Thumb Spica', '', '', '["Standard size fits virtually all patients.", "Flex panel allows for custom off-the-shelf fit.", "Flagless design enables 100% capture of the thumb.", "Adjustable radial and volar stays.", "Non-porous material minimizes moisture and dirt retention.", "Breathable, minimal irritation.", "One-hand, effortless fastening.", "Malleable and palmar stays for tailored rehab.", "Universal fit reduces inventory needs.", "Low-profile for easy compliance.", "Natural hand & thumb motion."]'::jsonb, '["Incomplete fractures", "Tendonitis", "Soft tissue injuries", "Post-cast support for healing", "Gamekeeper''s thumb", "Dequervain''s tendonitis", "Scaphoid injuries"]'::jsonb, '{"Size": ["X-Small", "Standard", "X-Large"], "Side": ["Right", "Left"]}'::jsonb, '["L3809"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'universal-wrist', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Universal 8" Wrist Brace', '', '', '["Breathable for all-day comfort.", "Tailored recovery with malleable stays.", "One-size-fits-most, minimizes inventory.", "One-pull, one-hand easy fastening.", "Customizable palmar stability."]'::jsonb, '["Carpal tunnel", "Incomplete fractures", "Tendonitis", "Soft tissue injuries", "Post-cast support for healing"]'::jsonb, '{"Side": ["Right", "Left"]}'::jsonb, '["L3908"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'post-op-shoe', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Ovation Square Toe Post-Op Shoe', '', '', '["Extended rocker sole is both rigid and durable.", "High ankle strap to allow for proper fit.", "Removable insole accommodates for additional dressings and swelling.", "Unisex (fits both men and women).", "Breathable Mesh Upper.", "Reinforced Heel Counter and Support.", "Sole materials reduce sliding.", "Cushioned rocker bottom design.", "Open toe and heel for extra comfort.", "Features easy contact closure."]'::jsonb, '["Broken toes", "Metatarsal fractures", "Foot and ankle sprains", "Broken Toes", "Metatarsal Fractures", "Foot and Ankle Sprains"]'::jsonb, '{"Size": ["X-Small", "Small", "Medium", "Large", "X-Large", "Small/Medium", "Medium/Large"]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'pressure-relief-pad', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Ovation Pressure Relief Pad', 'With removable hexes and a comfortable material', '', '["Provides convenient pressure relief.", "Allows for fast and efficient clinical application.", "Made from non-absorbable material that lasts."]'::jsonb, '["Pressure Relief for Soft-Tissue Injuries", "Shear Reduction Plantar Surface of Foot", "Treatment of Diabetic Ulcer"]'::jsonb, '{"Size": ["X-Small", "Small", "Medium", "Large", "X-Large"]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'shoulder-immobilizer', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Shoulder Abduction Sling', '', '', '["Provides shoulder abduction, promoting effective healing and recovery.", "The pillow portion rests comfortably on the waist to support the arm, alleviating strain.", "Easy to adjust with hook and loop straps.", "Made from breathable cotton for enhanced comfort and wearability.", "Durable cotton sling ensures long-lasting use and optimal support.", "Hook and loop closure adjustments on all straps allow for a personalized fit.", "Fits both the right and left arm, adding to its versatility.", "The waist strap helps prevent shoulder rotation, promoting effective healing.", "Included shoulder pad offers additional comfort.", "Figure-8 shoulder orthosis effectively supports the clavicle, facilitating recovery.", "Easily adjustable hook and loop closures allow for a personalized, secure fit.", "Padded straps enhance comfort, promoting increased patient compliance."]'::jsonb, '[]'::jsonb, '{"Size": ["Small", "Medium", "Large", "X-Small", "X-Large"]}'::jsonb, '["L3670", "L3650"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'arm-sling', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Arm Sling With Padded Shoulder', '', '', '["Envelope style design securely cradles the arm, providing optimal support.", "Comfort pad on the shoulder strap enhances patient compliance by reducing pressure and discomfort.", "Easy to adjust with hook and loop straps, ensuring a secure and personalized fit."]'::jsonb, '[]'::jsonb, '{"Size": ["X-Small", "Small", "Medium", "Large", "X-Large"]}'::jsonb, '["L3670"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'gauze', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Gauze Sponges', '', '', '["Ideal for dressing, cleaning, prepping, or packing wounds.", "Stringent manufacturing controls guarantee clean, debris-free packaging.", "Folded edges prevent lint and unraveling.", "Individually packaged to prevent intrusion of dust and contaminants.", "Sterile peel pouches facilitate easy opening.", "Absorbent, breathable, low-lint fabric helps stop bleeding and accelerates the healing process.", "Latex-free gauze provides ample stretch, easily conforming to various body parts.", "Sticks to itself, reducing need for excess tape.", "Allows for some controlled movement and soft-tissue swelling."]'::jsonb, '[]'::jsonb, '{"Size": ["Sterile 2x2 12ply", "Sterile 3x3 12ply", "Sterile 4x4 12ply", "Non-Sterile 2x2 12ply", "Non-Sterile 3x3 12ply", "Non-Sterile 4x4 12ply", "Non-Sterile 2x2 8ply", "Non-Sterile 3x3 8ply", "Non-Sterile 4x4 8ply", "2\" x 4.1 yd", "3\" x 4.1 yd", "4\" x 4.1 yd"]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'tape', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Cloth Tape', '', '', '["Serrated edges for easy tear.", "Strong residue-free adhesive supports long term use.", "Latex-free.", "Silk like texture feels smooth against the skin."]'::jsonb, '[]'::jsonb, '{"Size": ["1\" x 9.8 yd", "2\" x 9.8 yd"]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'compression-wrap', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Ovation Self-Adhering Compression Wrap', '', '', '["Self-adhesive, eliminating the need for clips or fasteners.", "Will not stick to skin, only to itself, offering great flexibility for multiple applications, without irritation.", "Wide range of practical applications as a compression bandage, support wrap, I.V. holder, and securer of monitors.", "Clip closures ensure a secure and personalized fit.", "Bandage maintains elasticity after multiple uses and washings.", "Soft texture and breathable materials ensure comfortable all-day wear.", "Provides comfortable support during various activities."]'::jsonb, '[]'::jsonb, '{"Size": ["2\" x 5 yd", "3\" x 5 yd", "4\" x 5 yd", "6\" x 5 yd"]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'elastic-bandage', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Elastic Bandage with the Alligator Clips, 2", 12 Rolls', '', '', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'casting-tape', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Casting Tape', '', '', '["Incorporates our \"Reactive Resin\", a water activated resin that adapts to pressure generated by the applicant.", "Soft and comfortable right out of the package, releases smoothly off the roll.", "Abrasive-free, will not catch on clothing or fray at the ends.", "Quality polyester ensures undercast comfort and effective moisture wicking.", "Strong and durable, yet easy to tear.", "Porous material allows the skin to breathe.", "Suitable for use with all casting materials.", "Suitable for use with all casting material and applications.", "Knitted polyester that is conformable and provides complete coverage.", "Reliable and consistent material that is smooth, strong, and hypoallergenic."]'::jsonb, '[]'::jsonb, '{"Size": ["2\" x 4 yd", "3\" x 4 yd", "4\" x 4 yd", "6\" x 4 yd", "2\" x 3 yd", "3\" x 3 yd", "4\" x 3 yd", "6\" x 3 yd", "1\"", "2\"", "3\"", "4\"", "6\""]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'roll-splint', 'pdf', 'Manufacturer PDF', 'Ovation Coded Product Catalog 2026', 'Ovation Premium Fiberglass Roll Splint', '', '', '["Easily conformable, won''t delaminate or wrinkle on application.", "Hardens within 3-5 minutes after treatment.", "Included sealing rod helps preserve the product between uses.", "Quick set time, ultra conformable, and easy to apply.", "A superior option in every major category, from padding and conformability, to ease of use and performance.", "Water repellent fabric technology channels and drains excess water, drying in less than half the time of fiberglass.", "20% lighter than a fiberglass splint and offers 90% more X-Ray transmittance.", "Can be treated as general waste, eliminating medical waste disposal costs.", "Non-Woven material eliminates sharp edges irritating the patient''s skin."]'::jsonb, '[]'::jsonb, '{"Size": ["2\" x 15 ft", "3\" x 15 ft", "4\" x 15 ft", "5\" x 15 ft"]}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'ankle-stirrup', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/foam-ankle-stirrups/', 'Foam Ankle Stirrups', '', 'Foam Ankle Stirrups provide the stability and relief necessary for recovery. The stirrups feature a low-profile design and a premium foam that conforms to the ankle. Easily fits in shoes.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/01-2020B-FOAM-ANLLE-STIRRUP-BLACK-ANGLE.jpg", "caption": "Angle view — Black"}, {"url": "https://www.ovationmed.com/app/uploads/2023/07/02-2020B-FOAM-ANLLE-STIRRUP-BLACK-FRONT.jpg", "caption": "Front view — Black"}, {"url": "https://www.ovationmed.com/app/uploads/2023/07/03-2020B-FOAM-ANLLE-STIRRUP-BLACK-SIDE.jpg", "caption": "Side view — Black"}]'::jsonb, '[{"Part Number": "2120B", "Description": "Foam Ankle Stirrup Black", "Size": "Youth/Universal", "Product Sizing Details": "Up to 5′"}, {"Part Number": "2020B", "Description": "Foam Ankle Stirrup Black", "Size": "Standard/Universal", "Product Sizing Details": "5’1 – up"}, {"Part Number": "2120W", "Description": "Foam Ankle Stirrup White", "Size": "Youth/Universal", "Product Sizing Details": "Up to 5′"}, {"Part Number": "2020W", "Description": "Foam Ankle Stirrup White", "Size": "Standard/Universal", "Product Sizing Details": "5’1 – up"}]'::jsonb, 'For left or right foot.', now()),
  ('ovation-medical', 'nu-form-ankle-brace', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/nu-form-ankle-brace/', 'Nu-Form™ Ankle Brace', '', 'Our patented Nu-Form™ Ankle Brace combines the best features of a classic lace-up figure-8 with the support of an ankle stirrup into a low-profile, lightweight, and breathable solution.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/01-FUSION-SERIES-ANKLE-BRACE-QUARTERTURN_1.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'lace-up-ankle', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/lace-up-ankle-brace/', 'Lace-Up Ankle Brace', '', 'The Lace-Up Ankle Brace is a trusted solution specifically designed to provide stability and support for a variety of ankle conditions. Constructed from ballistic nylon this ankle support aids in reducing swelling and promoting healing. Its user-friendly design seamlessly integrates into patients'' footwear, ensuring ease of use and convenience.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/01-ALL-BLACK-ANKLE-STRAP-46-e1690925078866.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'neoprene-knee', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/neoprene-knee-support/', 'Neoprene Knee Support with Stabilized Patella', '', 'The Neoprene Knee Support with Stabilized Patella is a comfortable pull-on style brace for patients needing extra support.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/01-45005-NEOPRENE-KNEE-SUPPORT-WITHSTABILIZED-PATELLA-ANGLED.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'game-changer-oa', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/the-game-changer-universal-oa-knee-brace/', 'The Game Changer™ OA Knee Brace', '', 'The Game Changer™ is a universal offloading brace for patients suffering from osteoarthritic knee pain (OA). The brace will fit virtually all patients, is lightweight, functional, and extremely low profile. The single upright design treats both medial and lateral knee pain.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/01-49002-GEN-2-GAME-CHANGER-OA-KNEE-5.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'compact-pro-rom', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/compact-pro-rom-post-op-knee-brace-standard/', 'Compact Pro ROM Post-Op Knee Brace', '', 'The Compact Pro ROM Post-Op Knee Brace is a high quality solution designed for the treatment of various types of knee injuries and surgeries. It offers an adjustable fit, comfort, and stability, making it ideal for patients of varying heights and sizes. The brace is available in standard and cool wrap versions and in standard or XL sizes.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/08/02-51500-COMPACT-PRO-POST-OP-KNEE-6-e1691214732991.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'thumb-spica', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/nu-form-thumb-spica/', 'Nu-Form™ Thumb Spica', '', 'Ovation''s patented Nu-Form™ Thumb Spica represents the biggest advancement in the category in over 30 years. Nu-Form technology enables an unprecedented combination of comfort, protection, and a custom fit that would not be possible using the conventional cut and sew method. The Nu-Form''s adaptable thumb cradle is more than suitable for minor ailments and a superior option for complex thumb injuries. Versa-Fit technology means one size fits nearly all patients.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/03-51075-THUMB-SPLICE-RIGHT-MEDIUM-3.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'versa-fit-wrist', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/versa-fit-wrist-brace/', 'Versa-Fit™ Wrist Brace', '', 'Our patented Versa-Fit™ Wrist Brace is the first off-the-shelf, custom fitting wrist support. The Versa offers optimal support and immobilization while allowing unrestricted motion of the hand and thumb. The Versa-Fit™ automatically adjusts and conforms to each patient''s anatomy, allowing one size to fit nearly all patients.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/03-59075-2-VERSA-FIT-BRACE-RIGHT-STANDARD-3-e1691080542842.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'universal-wrist', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/universal-8-wrist-brace/', 'Universal 8" Wrist Brace', '', 'Our Universal 8″ Wrist Brace provides secure immobilization of the wrist while maintaining full motion of the hand and fingers. With its universal sizing and adjustable features, it is a versatile solution for patients and healthcare professionals.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/03-59070-8IN-UNIVERSAL-WRIST-RIGHT-HAND-3.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'gen2-walking-boot', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/gen-2-walking-boot-tall-air/', 'Gen 2® Walking Boot', '', 'Ovation''s patented Gen 2® Walking Boot has been validated as the most advanced double upright walker on the market by healthcare professionals worldwide. Designed with the patient in mind, our Gen 2® eliminates all of the issues associated with old style walking boots. Lightyears ahead of its competition, the Gen 2® is the best option for your patients.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/08/01-10007BLU-STANDARD-PNEUMATIC-WALKER-1.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'nu-form-back', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/nu-form-universal-back-brace-l0627-l0642/', 'Nu-Form™ Universal Back Brace', '', 'Ovation''s patented Nu-Form™ Universal Back Brace (L0627/L0642) is the first brace to have a completely breathable posterior panel and uniquely effective pressure relief zone over the spinous process. Nu-Form manufacturing technology has allowed us to produce a lightweight, low-profile, and extremely durable brace that we backed with a 5-year warranty.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/08/01-62001U-NIVERSAL-BACK-BRACE-FRONT.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'ls-double-pull-back', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/lso-v1-universal-double-pull-back-braces-l0627/', 'Universal LS Double-Pull Back Brace', '', 'The Universal LS Double-Pull Back Brace is universally sized and easily adjustable. This brace reduces load on the intervertebral discs by producing intercavitary pressure. Designed with a double-pull pulley system for adjustable compression and quality materials for breathability and comfort, these braces are a great solution for various back conditions. Provides coverage, extending from L-1 to below L-5 vertebra.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/08/01-61001-LS-DOUBLE-PULL-FRONT.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'lumbar-support', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/elastic-lumbar-support-2/', 'Elastic Lumbar Support', '', 'Ovation Medical''s Elastic Lumbar Support is versatile and easy-to-use, offering abdominal and lumbar support. Made with quality materials that increase breathability and enhance comfort.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/02-OVATION-MEDICAL-BRACE-FOLDED.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'hybrid-night-splint', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/hybrid-night-splint/', 'Hybrid Night Splint', '', 'Traditionally, orthopedic bracing companies have provided only two night splint options for treating plantar fasciitis and heel pain. These offerings have led to frustrated doctors, non-compliant patients, and huge gaps in recovery outcomes. Ovation''s patented Hybrid Night Splint offers more comfort than a posterior splint and better functionality than a dorsal, making it the best of both worlds.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/01-HYBRID-SPLINT-42.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'night-splint', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/posterior-night-splint/', 'Posterior Night Splint', '', 'Ovation''s take on the classic posterior night splint is thoughtfully elevated to provide enhanced comfort. Adjustable bilateral straps allow for a comfortable and gradual stretch of the Plantar Fascia and Achilles Tendon.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/01-31007-POSTERIOR-NIGHT-15.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'post-op-shoe', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/ovation-square-toe-post-op-shoe/', 'Ovation Square Toe Post-Op Shoe', '', 'The Ovation Square Toe Post-Op Shoe is extremely durable and allows for customizations, such as in the case of a diabetic patient. Designed to fit both men and women.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/01-733-005-SQUARE-TOE-MESH-TOP-POST-OP-SHOE-ANGLE.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'pressure-relief-pad', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/ovation-pressure-relief-pad/', 'Ovation Pressure Relief Pad', '', 'Introducing our Pressure Relief Pad, a post-op insert designed for convenient pressure relief and efficient clinical application. With removable hexes and a comfortable, durable non-absorbable material, it provides effective treatment for soft-tissue injuries, shear reduction on the plantar surface of the foot, and diabetic ulcers.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/03-733-005PRP-PRESSURE-RELIEF-PAD-TOP-HOLE-BIG.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'shoulder-immobilizer', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/shoulder-abduction-sling/', 'Shoulder Abduction Sling', '', 'The Shoulder Abduction Sling offers ideal support for post-operative recovery and injury rehabilitation. Designed to keep your shoulder in a restful, healing position, it provides comfort while ensuring optimal recovery conditions.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/08/04-OVATION-MEDICAL-2023-04-28-KBJE1888.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'arm-sling', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/arm-sling-with-padded-shoulder-2/', 'Arm Sling With Padded Shoulder', '', 'A simple yet highly effective solution for upper limb support. Designed with patient comfort in mind, this sling is an excellent choice for post-operative care or injury recovery.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/01-58015-ARM-SLING-WITH-PADDED-SHOLDER.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'gauze', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/gauze-sponge-sterile/', 'Gauze Sponges', '', '', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2024/04/Guaze-Sponges.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'tape', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/cloth-tape/', 'Cloth Tape', '', '', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2024/04/Cloth-Tape.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'compression-wrap', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/ovation-self-adhering-compression-wrap/', 'Ovation Self-Adhering Compression Wrap', '', 'This easy-to-tear, self-adhering elastic bandage offers controlled compression and non-slip support. It''s made from a fabric-based material that ensures comfortable and effective wear.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2024/04/blue-tape.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'elastic-bandage', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/elastic-bandage-with-alligator-clips/', 'Elastic Bandage with the Alligator Clips, 2", 12 Rolls', '', 'Made with high quality materials, our elastic bandage will maintain its elasticity through multiple washings. Soft, breathable fabric and a secure personalized fit make it perfect for all day wear.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/Elastic-Bandgae-with-Alligator-Clips.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'casting-tape', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/ovation-premium-fiberglass-casting-tape/', 'Casting Tape', '', 'Made using our ''Reactive Resin'' formula, Ovation''s Premium Fiberglass Casting Tape will adapt to pressure generated by the applicant making for effortless molding and a smooth, durable finished product. Available in a variety of colors including Blue, Black, White, and Pink.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/CastingTape.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now()),
  ('ovation-medical', 'roll-splint', 'website', 'Manufacturer Website', 'https://www.ovationmed.com/products-medical/ovation-premium-fiberglass-roll-splint/', 'Ovation Premium Fiberglass Roll Splint', '', 'Our 15′ continuous fiberglass roll is designed for quick application and ease of use, ideal for short-term immobilization. Each roll comes with a clip for resealing.', '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, '[{"url": "https://www.ovationmed.com/app/uploads/2023/07/3IN-PERFORMANCE-SPLINTING-1-e1689887467973.jpg", "caption": "Website product image"}]'::jsonb, '[]'::jsonb, null, now())
