-- ============================================================================
-- Partner 360 · Ovation Medical — source captures (v3): PDF + Website for all 25
-- PDF = features/clinical/codes/options (2026 catalogs). Website = description + primary
-- image for every product; Foam Ankle Stirrups also carries its full gallery + sizing chart.
-- Repoints catalog images to absolute URLs. Run after product_content_multisource.sql. Idempotent.
-- ============================================================================

update public.product_content set image = 'https://hcpsonlineordering.netlify.app' || image
where manufacturer = 'ovation-medical' and image like '/assets/%';

on conflict (manufacturer, page_key, source) do update set source_label=excluded.source_label, source_url=excluded.source_url, name=excluded.name, tagline=excluded.tagline, description=excluded.description, features=excluded.features, clinical_applications=excluded.clinical_applications, options=excluded.options, billing_codes=excluded.billing_codes, images=excluded.images, sizing_rows=excluded.sizing_rows, sizing_note=excluded.sizing_note, captured_at=excluded.captured_at;
